/**
 * Switches between peer views of one subject (`design/components/tabs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tabs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/tabs'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  classes,
  createDerived,
  elementRef,
  mergeParts,
  ownerContext,
  provide,
  revealInline,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/overlays/tabs.module.css'
import Badge from '../structure/Badge'

export type TabsOrientation = NonNullable<TabsProps['orientation']>

export interface TabDescriptor {
  value: string
  label: string
  icon?: IconRole
  count?: number
  disabled?: boolean
}

export interface TabsProps {
  /**
   * One `Tabs.Content` per tab.
   */
  children: JSX.Element
  defaultValue?: string
  /**
   * Keeps inactive panels mounted and `hidden` (Radix `forceMount`), so a form being edited or
   * an embedded player survives a tab switch. The default unmounts them, so the common case does
   * not pay to mount everything.
   */
  keepMounted?: boolean
  onChange?: (value: string) => void
  /**
   * Vertical is the same component on its side, with the rule down the start edge instead of
   * along the bottom. Use it when labels are long enough that a horizontal strip would wrap,
   * because wrapped tabs no longer read as peers.
   */
  orientation?: 'horizontal' | 'vertical'
  tabs: TabDescriptor[]
  value?: string
}

/** What Tabs hands its compound parts. */
export interface TabsOwner {
  readonly api: zag.Api
  readonly keepMounted: Exclude<TabsProps['keepMounted'], undefined>
}

/** Switches between peer views of one subject. */
export default function Tabs(given: TabsProps): JSX.Element {
  const props = mergeProps(
    { orientation: 'horizontal', keepMounted: false } as Defaults<
      TabsProps,
      'orientation' | 'keepMounted'
    >,
    claimSlot(given),
  )
  return scope(() => {
    provide(ownerContext<TabsOwner>('Tabs'), {
      get api() {
        return api.value
      },
      get keepMounted() {
        return props.keepMounted
      },
    })
    const uid = createUniqueId()
    const list = elementRef<HTMLElement>()
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          value: props.value,
          defaultValue: props.defaultValue ?? props.tabs[0]?.value,
          orientation: props.orientation,
          onValueChange: (details) => {
            props.onChange?.(details.value)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        revealInline(list.value, list.value?.querySelector('[data-state="active"]'), true)
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [list.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    const effect2 = () => {
      revealInline(list.value, list.value?.querySelector('[data-state="active"]'))
    }
    watchEffect(
      createMemo(() => api.value.value),
      effect2,
      false,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'Tabs',
        element: () => list.value,
        state: () => ({
          value: api.value.value ?? null,
          tabs: props.tabs.map((tab) => ({
            id: tab.value,
            label: tab.label,
            ...(tab.disabled === true ? { disabled: true } : {}),
          })),
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) => value === api.value.value || api.value.setValue(value),
          },
        },
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <div {...mergeParts(api.value.getRootProps(), { class: styles.root, 'data-member': 'tabs' })}>
        {/* list */}
        <div
          {...mergeParts(api.value.getListProps(), {
            class: styles.list,
            'data-tabs-part': 'list',
          })}
          ref={list.attach}
        >
          <Each of={props.tabs} by={(tab) => tab.value} renew>
            {(tab) => (
              <button
                {...mergeParts(
                  api.value.getTriggerProps({ value: tab.value, disabled: tab.disabled }),
                  {
                    class: styles.trigger,
                    'data-tabs-part': 'tab',
                    'data-state': api.value.value === tab.value ? 'active' : 'inactive',
                    'data-disabled': tab.disabled ? '' : undefined,
                  },
                )}
              >
                {tab.icon !== undefined ? (
                  <span class={styles.glyph}>
                    <Icon name={tab.icon} size="sm" />
                  </span>
                ) : null}
                <span>{tab.label}</span>
                {tab.count !== undefined ? (
                  <span class={styles.count}>
                    <Badge tone={api.value.value === tab.value ? 'accent' : 'neutral'}>
                      {String(tab.count)}
                    </Badge>
                  </span>
                ) : null}
              </button>
            )}
          </Each>
          {/* indicator */}
          <div
            {...mergeParts(api.value.getIndicatorProps(), {
              class: classes(styles.indicator, styles.slide),
              style: {
                'inline-size':
                  props.orientation === 'vertical'
                    ? undefined
                    : Object(api.value.getIndicatorProps().style)['--width'],
                'block-size':
                  props.orientation === 'vertical'
                    ? Object(api.value.getIndicatorProps().style)['--height']
                    : undefined,
              },
            })}
          />
        </div>
        {props.children}
      </div>
    )
  })
}
